import java.util.*;

import lombok.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        while (in.hasNextLine()) {
            String[] d = in.nextLine().split(";");
            Pesanan.PesananBuilder b = Pesanan.builder().kode(d[0]).pelanggan(d[1]);
            if (d.length > 2) {
                b.kurir(d[2]);
            }
            System.out.println(b.build());
        }
    }
}

@Builder
@ToString
class Pesanan {
    private String kode;
    private String pelanggan;
    @Builder.Default
    private String kurir = "reguler";
}
